const $=s=>document.querySelector(s);const ns='http://www.w3.org/2000/svg';const fmt=n=>String(n).replace('-','−');const storage={get(k){try{return localStorage.getItem('fondasi-distributive-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-distributive-'+k,v);return true}catch{return false}}};function svg(tag,attrs,text){const e=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;$('#diagram').append(e)}function area(){const a=Number($('#height').value),b=Number($('#width-b').value),c=Number($('#width-c').value);$('#height-out').value=a;$('#width-b-out').value=b;$('#width-c-out').value=c;$('#diagram').replaceChildren();const x=65,y=60,unit=38,h=a*unit;svg('rect',{x,y,width:b*unit,height:h,fill:'#b9ceae',stroke:'#244d40','stroke-width':2});svg('rect',{x:x+b*unit,y,width:c*unit,height:h,fill:'#e4bcaa',stroke:'#244d40','stroke-width':2});for(const [tx,ty,text]of [[x+b*unit/2,y-20,`b = ${b}`],[x+(b+c/2)*unit,y-20,`c = ${c}`],[x-30,y+h/2,`a=${a}`],[x+b*unit/2,y+h/2,`${a*b}`],[x+(b+c/2)*unit,y+h/2,`${a*c}`]])svg('text',{x:tx,y:ty,'text-anchor':'middle'},text);svg('text',{x:x+(b+c)*unit/2,y:y+h+40,'text-anchor':'middle'},`lebar total = ${b+c}`);$('#area-equation').textContent=`${a}(${b} + ${c}) = ${a*b} + ${a*c} = ${a*(b+c)}`;$('#area-feedback').textContent=`Luas seluruh bidang ${a} × ${b+c} = ${a*(b+c)}. Dua bagiannya memiliki luas ${a*b} dan ${a*c}. Jumlahnya sama karena bidang hanya dibagi, bukan ditambah atau dikurangi.`}for(const id of ['#height','#width-b','#width-c'])$(id).addEventListener('input',area);area();const pairs=[{left:'3(x + 2)',right:'3x + 6',a:x=>3*(x+2),b:x=>3*x+6,same:true,why:'Sifat distributif memberi 3(x + 2) = 3x + 6 untuk semua x bilangan real.'},{left:'3(x + 2)',right:'3x + 2',a:x=>3*(x+2),b:x=>3*x+2,same:false,why:'Suku 2 di dalam kurung juga harus dikalikan 3. Bentuk yang benar adalah 3x + 6.'},{left:'−(x − 2)',right:'−x + 2',a:x=>-(x-2),b:x=>-x+2,same:true,why:'Pengali −1 berlaku pada x dan −2, sehingga hasilnya −x + 2.'},{left:'−2(x − 3)',right:'−2x − 6',a:x=>-2*(x-3),b:x=>-2*x-6,same:false,why:'(−2)(−3) = +6. Bentuk yang benar adalah −2x + 6.'}];function compare(){const p=pairs[Number($('#comparison').value)],x=Number($('#test-x').value),a=p.a(x),b=p.b(x);$('#test-x-out').value=fmt(x);$('#comparison-values').replaceChildren();for(const s of [`${p.left} → ${fmt(a)}`,`${p.right} → ${fmt(b)}`]){const line=document.createElement('div');line.textContent=s;$('#comparison-values').append(line)}$('#comparison-feedback').textContent=`Pada x = ${fmt(x)}, kedua nilai ${a===b?'sama':'berbeda'}. ${p.why} `+(p.same?'Kesetaraan umumnya dijelaskan oleh sifat distributif, bukan hanya oleh percobaan ini.':'Contoh ini menunjukkan kedua bentuk tidak selalu setara.')}$('#comparison').addEventListener('change',compare);$('#test-x').addEventListener('input',compare);compare();
const examples=[{steps:[{expr:'2(x + 3) − (x − 4)',choices:['2x + 6 − x + 4','2x + 3 − x − 4'],correct:0,why:'Kalikan x dan 3 dengan 2; kalikan x dan −4 dengan −1.',wrong:'Pengali di luar kurung berlaku ke setiap suku. Perhatikan juga (−1)(−4) = +4.'},{expr:'2x + 6 − x + 4',choices:['(2 − 1)x + (6 + 4)','(2 + 1)x + (6 − 4)'],correct:0,why:'Gabungkan suku x dengan tanda masing-masing, lalu konstanta.',wrong:'Suku −x memiliki koefisien −1, sedangkan konstanta +4 tetap positif.'},{expr:'(2 − 1)x + (6 + 4)',choices:['x + 10','x + 2'],correct:0,why:'2 − 1 = 1 dan 6 + 4 = 10.'}],result:'x + 10'},{steps:[{expr:'3x + 2x − 4 + 7',choices:['(3 + 2)x + (−4 + 7)','5x − 11'],correct:0,why:'Suku x sejenis. Kelompokkan konstanta dengan tandanya.',wrong:'Konstanta yang dijumlahkan adalah −4 dan +7, bukan −4 dan −7.'},{expr:'(3 + 2)x + (−4 + 7)',choices:['5x + 3','8x'],correct:0,why:'Hasilnya 5x + 3. Konstanta 3 tidak sejenis dengan 5x.',wrong:'Suku konstanta tidak dapat digabungkan ke koefisien x.'}],result:'5x + 3'},{steps:[{expr:'−2(x − 3) + x',choices:['−2x + 6 + x','−2x − 6 + x'],correct:0,why:'Pengali −2 memberi −2x dan +6.',wrong:'Negatif dikali negatif menghasilkan positif: (−2)(−3) = +6.'},{expr:'−2x + 6 + x',choices:['−x + 6','−3x + 6'],correct:0,why:'Koefisien x adalah −2 + 1 = −1.',wrong:'Suku +x memiliki koefisien +1. Jadi −2 + 1 = −1.'}],result:'−x + 6'}];let step=0;function draw(){const e=examples[Number($('#example').value)];$('#choices').replaceChildren();if(step===e.steps.length){$('#expression').textContent=e.result;const p=document.createElement('p');p.textContent='Contoh selesai. Pilih contoh lain atau ulangi.';$('#choices').append(p);return}const s=e.steps[step];$('#expression').textContent=s.expr;s.choices.forEach((label,i)=>{const b=document.createElement('button');b.textContent=label;b.type='button';b.addEventListener('click',()=>{if(i!==s.correct){$('#step-feedback').textContent=s.wrong;return}const next=step+1===e.steps.length?e.result:e.steps[step+1].expr,li=document.createElement('li');li.textContent=`${s.expr} = ${next}. ${s.why}`;$('#history').append(li);$('#step-feedback').textContent='Tepat. '+s.why;step++;draw()});$('#choices').append(b)})}function reset(){step=0;$('#history').replaceChildren();$('#step-feedback').textContent='Pilih bentuk yang menjaga nilai ekspresi untuk semua x bilangan real.';draw()}$('#example').addEventListener('change',reset);$('#reset').addEventListener('click',reset);reset();$('#check').addEventListener('click',()=>{const v=document.querySelector('[name=awal]:checked')?.value;$('#check-feedback').textContent=!v?'Pilih satu dugaan terlebih dahulu.':v==='correct'?'Tepat. Tiga paket masing-masing berisi x + 2, sehingga ada 3x dan 6 benda tambahan.':'Pengali 3 berlaku pada seluruh kelompok x + 2. Jadi hasilnya 3x + 6, bukan hanya mengubah salah satu suku.'});
const qs=[{t:'Pada 4(x + 3) = 4x + □, berapa isi kotak?',n:12,d:1,h:'Suku 3 juga dikalikan 4.',why:'4 × 3 = 12, sehingga 4(x + 3) = 4x + 12.'},{t:'Pada −(x − 5) = −x + □, berapa isi kotak?',n:5,d:1,h:'Tanda minus di depan kurung berarti pengali −1.',why:'(−1)(−5) = +5.'},{t:'Pada −3(x + 2) = −3x + □, berapa isi kotak? Tulis bilangannya beserta tanda.',n:-6,d:1,h:'Kalikan −3 dengan +2.',why:'(−3) × 2 = −6, sehingga bentuknya −3x − 6.'},{t:'Pada 7x − 2x = □x, berapa isi kotak?',n:5,d:1,h:'Gabungkan koefisien 7 dan −2.',why:'7 − 2 = 5, sehingga hasilnya 5x.'},{t:'Konstanta hasil penyederhanaan 2(x + 3) − (x − 4) adalah…',n:10,d:1,h:'Setelah kurung dibuka, konstantanya 6 dan +4.',why:'Bentuk sederhananya x + 10, sehingga konstantanya 10.'},{t:'Koefisien x hasil penyederhanaan −2(x − 3) + x adalah…',n:-1,d:1,h:'Setelah kurung dibuka, koefisiennya −2 dan +1.',why:'−2x + 6 + x = −x + 6, dengan koefisien x yaitu −1.'},{t:'Jika x = 2, berapa nilai 3(x + 2)?',n:12,d:1,h:'Hitung isi kurung lebih dahulu atau gunakan 3x + 6.',why:'3(2 + 2) = 12. Bentuk 3x + 6 juga bernilai 12.'}];const solved=new Set();function progress(){$('#progress').textContent=`${solved.size} dari 8 latihan telah dijawab dengan tepat.`}function parse(s){const m=s.trim().replace(/−/g,'-').match(/^([+-]?\d+)(?:\s*\/\s*([+-]?\d+))?$/);if(!m)return null;const n=Number(m[1]),d=m[2]?Number(m[2]):1;return Number.isSafeInteger(n)&&Number.isSafeInteger(d)&&d!==0&&Math.abs(n)<=1000000&&Math.abs(d)<=1000000?{n,d}:null}$('#questions').innerHTML=qs.map((q,i)=>`<div class="question"><h3>Latihan ${i+1}</h3><p>${q.t}</p><form class="number-form" data-q="${i}"><label for="answer${i}">Jawaban latihan ${i+1}, satu bilangan</label><div class="answer-line"><input id="answer${i}" type="text" inputmode="text" placeholder="misalnya -6" required autocomplete="off" aria-describedby="feedback${i}"><button class="button">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.h}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('[data-q]').forEach(form=>form.addEventListener('submit',ev=>{ev.preventDefault();const i=Number(form.dataset.q),v=parse($('#answer'+i).value),q=qs[i],ok=v&&v.n*q.d===q.n*v.d;$('#feedback'+i).className='feedback '+(ok?'correct':'incorrect');$('#feedback'+i).textContent=!v?'Tulis satu bilangan, misalnya -6. Jika memakai pecahan, penyebut tidak boleh nol.':ok?'Tepat. '+q.why:'Belum tepat. Periksa pengali setiap suku dan tanda yang ikut bersamanya. Gunakan petunjuk jika perlu.';if(ok)solved.add(i);progress()}));$('#check-like').addEventListener('click',()=>{const v=document.querySelector('[name=like]:checked')?.value,ok=v==='correct';$('#like-feedback').className='feedback '+(ok?'correct':'incorrect');$('#like-feedback').textContent=!v?'Pilih satu jawaban terlebih dahulu.':ok?'Tepat. x² dan x memiliki pangkat berbeda, sehingga bukan suku sejenis.':'Koefisien hanya digabungkan pada suku sejenis. x² dan x berbeda, sehingga bentuknya tetap 2x² + 3x.';if(ok)solved.add(7);progress()});$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#reflection-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan pada peramban ini.':'Catatan belum bisa disimpan. Salin jika ingin menyimpannya.'});function complete(){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#progress').textContent='Bacaan ditandai selesai ✓'}if(storage.get('complete')==='yes')complete();$('#complete').addEventListener('click',()=>{const ok=storage.set('complete','yes');complete();$('#complete-note').textContent=ok?'Kemajuan tersimpan. Kamu dapat kembali berlatih kapan saja.':'Selesai. Kemajuan belum dapat disimpan pada peramban ini.'});
